CREATE TRIGGER RefMaterial_Version_Create
	ON RefMaterial
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RMC_PK, 'RMC'
	FROM inserted
GO
CREATE TRIGGER RefMaterial_Version_Update
	ON RefMaterial
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RMC_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefMaterial_DataChangeHistory
	ON RefMaterial
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT RMC_PK, 'RMC' FROM inserted
	UNION
	SELECT RMC_PK, 'RMC' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefMaterial_DataProcessingResult_Delete
	ON RefMaterial
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.RMC_PK
	END
GO
